INSERT INTO `livros` (`id`, `titulo`, `autor`, `preco`, `categoria`, `destaque`, `imagem`, `sinopse`, `editora`, `publicacao`, `edicao`, `idioma`, `paginas`, `peso`, `idade`) VALUES
(1, 'Orgulho e Preconceito', 'Jane Austen', 'R$ 200,00', 'Romance', 0, '1.png', 'A jovem Elizabeth Bennet navega questões de casamento, moralidade e felicidade na Inglaterra do século XIX, em um dos maiores romances da literatura inglesa.', 'Penguin Companhia', '1813', '1ª edição especial', 'Português', '424', '420g', '14+'),
(2, 'Como Eu Era Antes de Você', 'Jojo Moyes', 'R$ 39,90', 'Romance', 1, '2.jpg', 'Louisa Clark, uma jovem otimista, se torna cuidadora de Will Traynor, um homem tetraplégico amargo mas brilhante. Uma história de amor transformadora.', 'Intrínseca', '2012', '1ª edição', 'Português', '384', '380g', '16+'),
(3, 'A Culpa é das Estrelas', 'Jhon Green', 'R$ 39,90', 'Romance', 1, '3.jpg', 'Hazel e Augustus são dois adolescentes com câncer que se conhecem em um grupo de apoio. Uma história de amor, vida e morte que comove o mundo inteiro.', 'Intrínseca', '2012', '1ª edição', 'Português', '288', '280g', '14+'),
(4, 'Diário de uma Paixão', 'Nicholas Sparks', 'R$ 34,90', 'Romance', 0, '4.jpg', 'Noah Calhoun e Allie Hamilton vivem um romance intenso separado pela guerra e pela distância social, numa história de amor eterno e inesquecível.', 'Arqueiro', '1996', '1ª edição', 'Português', '208', '200g', '14+'),
(5, 'Eleanor & Park', 'Rainbow Rowell', 'R$ 38,90', 'Romance', 0, '5.jpg', 'Eleanor e Park se encontram no ônibus escolar e formam uma conexão improvávelmas poderosa, em um romance sobre primeiros amores e ser diferente.', 'Galera Record', '2013', '1ª edição', 'Português', '320', '300g', '14+'),
(6, 'Simplesmente Acontece', 'Cecelia Ahern', 'R$ 42,90', 'Romance', 1, '6.jpg', 'Uma mulher descobre cartas misteriosas que mudam sua vida, numa narrativa mágica e encantadora sobre amor, destino e conexões inesperadas.', 'Sextante', '2004', '1ª edição', 'Português', '320', '310g', '16+'),
(7, 'O Morro dos Ventos Uivantes', 'Emily Brontë', 'R$ 32,90', 'Romance', 0, '7.jpg', 'Heathcliff e Catherine protagonizam um dos amores mais apaixonados e destrutivos da literatura, numa saga de obsessão e vingança nos páramos ingleses.', 'Martin Claret', '1847', '1ª edição revisada', 'Português', '384', '370g', '16+'),
(8, 'P.S. Eu Te Amo', 'Cecelia Ahern', 'R$ 36,90', 'Romance', 0, '8.jpg', 'Holly recebe cartas pósumas do marido que faleceu, cada uma guiando-a a redescobrir a vida e o amor. Uma história de perda, cura e recomeço.', 'Sextante', '2004', '1ª edição', 'Português', '310', '300g', '16+'),
(9, 'O Clube P.S. Eu Te Amo', 'Cecelia Ahern', 'R$ 36,90', 'Romance', 0, '9.jpg', 'Continuação emocionante da saga P.S. Eu Te Amo, onde Holly e suas amigas embarcam em novas jornadas de amor e autodescoberta.', 'Sextante', '2011', '1ª edição', 'Português', '320', '300g', '16+'),
(10, 'Anna e o Beijo Francês', 'Stephanie Perkins', 'R$ 37,90', 'Romance', 0, '10.jpg', 'Anna vai passar o último ano do ensino médio em Paris e encontra o charmoso Étienne St. Clair. Um romance doce ambientado na cidade do amor.', 'Galera Record', '2010', '1ª edição', 'Português', '416', '390g', '14+'),
(11, 'Um Dia', 'David Nicholls', 'R$ 36,90', 'Romance', 0, '11.jpg', 'Dexter e Emma se encontram no dia da formatura e se tornam amigos inseparáveis. O livro acompanha o mesmo dia - 15 de julho - ao longo de 20 anos.', 'Companhia das Letras', '2009', '1ª edição', 'Português', '448', '420g', '16+'),
(12, 'Amor & Gelato', 'Jenna Evans Welch', 'R$ 38,90', 'Romance', 0, '12.jpg', 'Lina vai para a Itália após a morte da mãe e descobre um diário e uma história de amor secreta que transforma completamente sua visão da vida.', 'Galera Record', '2017', '1ª edição', 'Português', '400', '370g', '14+'),
(13, 'Teto Para Dois', 'Beth O\'Lears', 'R$ 42,90', 'Romance', 1, '13.jpg', 'Dois estranhos dividem um apartamento por necessidade e acabam descobrindo que o amor pode surgir nos lugares mais improváveis.', 'Arqueiro', '2019', '1ª edição', 'Português', '352', '330g', '16+'),
(14, 'Leitura de Verão', 'Emily Henry', 'R$ 44,90', 'Romance', 0, '14.jpg', 'A escritora Harriet leva o verão numa cidade litorânea e descobre romances inesperados, segredos da família e o significado de ler e amar.', 'Intrínseca', '2022', '1ª edição', 'Português', '384', '360g', '16+'),
(15, 'É Assim Que Acaba', 'Collen Hoover', 'R$ 44,90', 'Romance', 0, '15.jpg', 'Uma história intensa e poderosa sobre um relacionamento abusivo e a coragem de se libertar. Colleen Hoover no seu melhor, mais sombrio e mais real.', 'Galera Record', '2016', '1ª edição', 'Português', '320', '300g', '18+'),
(16, 'É Assim Que Começa', 'Colleen Hoover', 'R$ 42,90', 'Romance', 0, '16.jpg', 'Prequel de É Assim Que Acaba, contando como Lily e Ryle se conheceram. Uma história de amor apaixonante que explora os sinais de alerta num relacionamento.', 'Galera Record', '2017', '1ª edição', 'Português', '320', '300g', '18+'),
(17, 'Amor(es) Verdadeiro(s)', 'Taylor Jenkins Reid', 'R$ 40,90', 'Romance', 0, '17.jpg', 'Uma mulher olha para trás e para frente no tempo para entender seus amores, suas escolhas e a pergunta: existe uma alma gêmea verdadeira?', 'Intrínseca', '2019', '1ª edição', 'Português', '352', '330g', '16+'),
(18, 'Corte de Espinhos e Rosas', 'Sarah J. Maas', 'R$ 49,90', 'Romance Fantasia', 1, '18.jpg', 'Feyre caça para sobreviver e acaba sendo capturada por uma criatura do mundo feérico. Uma história épica de amor proibido entre mundos.', 'Galera Record', '2015', '1ª edição', 'Português', '448', '430g', '16+'),
(19, 'A Lâmina Assassina', 'Sarah J. Maas', 'R$ 47,90', 'Romance Fantasia', 0, '19.jpg', 'A jovem assassina Celaena Sardothien deve participar de uma competição mortal para ganhar a liberdade, enquanto enfrenta poderes sobrenaturais.', 'Galera Record', '2012', '1ª edição', 'Português', '432', '410g', '16+'),
(20, 'A Rainha Vermelha', 'Victoria Aveyard', 'R$ 44,90', 'Romance Fantasia', 0, '20.jpg', 'Num mundo dividido entre Sangue de Prata e Sangue de Vermelho, Mare Barrow descobre poderes impossíveis e enfrenta uma revolução que pode destruir tudo.', 'Galera Record', '2015', '1ª edição', 'Português', '400', '380g', '14+'),
(21, 'Crepúsculo', 'Stephenie Meyer', 'R$ 39,90', 'Romance Fantasia', 0, '21.jpg', 'Bella Swan muda para Forks e se apaixona pelo misterioso Edward Cullen. Uma saga vampírica que conquistou leitores de todo o mundo.', 'Intrínseca', '2005', '1ª edição', 'Português', '432', '400g', '14+'),
(22, 'O Príncipe Cruel', 'Holly Black', 'R$ 46,90', 'Romance Fantasia', 1, '22.jpg', 'Jude é levada ao mundo feérico e precisa sobreviver às intrigas perigosas da corte. Um romance sombrio de poder, traição e amor inesperado.', 'Galera Record', '2018', '1ª edição', 'Português', '384', '360g', '16+'),
(23, 'Sombra e Ossos', 'Leigh Bardugo', 'R$ 48,90', 'Romance Fantasia', 0, '23.jpg', 'Alina descobre poderes de Invocadora de Luz e é levada para o exército do Grisha, onde o misterioso Darkling desperta algo que ela não esperava.', 'Galera Record', '2012', '1ª edição', 'Português', '368', '350g', '14+'),
(24, 'Caraval', 'Stephanie Garber', 'R$ 45,90', 'Romance Fantasia', 0, '24.jpg', 'Scarlett Dragna ganha o ingresso para o Caraval, um jogo lendário onde tudo pode ser real ou ilusão - inclusive o amor e a morte.', 'Galera Record', '2017', '1ª edição', 'Português', '416', '390g', '14+'),
(25, 'A Seleção', 'Kiera Cass', 'R$ 40,90', 'Romance Fantasia', 0, '25.jpg', 'Em plena competição para ser a esposa do príncipe, America Singer não quer participar - mas o Príncipe Maxon pode mudar tudo.', 'Galera Record', '2012', '1ª edição', 'Português', '336', '320g', '14+'),
(26, 'A Ponte Entre Reinos', 'Danielle L. Jensen', 'R$ 43,90', 'Romance Fantasia', 0, '26.jpg', 'Uma jovem é oferecida em casamento a um príncipe do mundo sobrenatural e descobre que fronteiras entre reinos guardam segredos e amores perigosos.', 'Galera Record', '2014', '1ª edição', 'Português', '368', '340g', '16+'),
(27, 'O Beijo Traiçoeiro', 'Erin Beaty', 'R$ 44,90', 'Romance Fantasia', 0, '27.jpg', 'Uma espiã disfarçada de dama da corte enfrenta intrigas políticas e um amor proibido numa história de aventura, segredos e traição.', 'Galera Record', '2016', '1ª edição', 'Português', '352', '330g', '14+'),
(28, 'Quarta Asa', 'Rebecca Yarros', 'R$ 54,90', 'Romance Fantasia', 1, '28.jpg', 'Violet Sorrengail entra na escola de pilotos de dragão e descobre que sobreviver é apenas o começo - o amor e a guerra são ainda mais implacáveis.', 'Galera Record', '2023', '1ª edição', 'Português', '528', '510g', '16+'),
(29, 'De Sangue e Cinzas', 'Jennifer L. Armentrout', 'R$ 49,90', 'Romance Fantasia', 0, '29.jpg', 'Poppy vive protegida por regras rígidas do reino, mas quando o Guarda Hawke aparece, ela descobre segredos que mudam tudo o que acreditava.', 'Galera Record', '2020', '1ª edição', 'Português', '496', '470g', '16+'),
(30, 'O Feitiço dos Espinhos', 'Margaret Rogerson', 'R$ 46,90', 'Romance Fantasia', 0, '30.png', 'Isobel é uma bordadeira lançada no mundo das fadas por seu poder único, onde o amor e a magia se entrelaçam em uma tapeçaria de consequências.', 'Galera Record', '2018', '1ª edição', 'Português', '320', '300g', '14+'),
(31, 'Gild', 'Raven Kennedy', 'R$ 47,90', 'Romance Fantasia', 0, '31.jpg', 'Filha de Midas, Auren é coberta de ouro e mantida em uma gaiola dourada. Uma história sobre liberdade, poder e amor em um mundo de fadas.', 'Galera Record', '2020', '1ª edição', 'Português', '432', '410g', '16+'),
(32, 'Estilhaça-me', 'Tahereh Mafi', 'R$ 44,90', 'Romance Fantasia', 0, '32.jpg', 'Juliette possui um toque letal e foi encarcerada por isso. Quando o misterioso Warner a recruta, ela descobre que seu poder é uma arma - e talvez uma dádiva.', 'Galera Record', '2011', '1ª edição', 'Português', '352', '330g', '14+'),
(33, 'Dinastia de Ladrões', 'Marry E. Pearson', 'R$ 49,90', 'Romance Fantasia', 0, '33.jpg', 'Uma ladra de memórias e um príncipe exilado precisam trabalhar juntos para recuperar o que foi roubado, descobrindo que o passado esconde mais segredos do que imaginam.', 'Galera Record', '2018', '1ª edição', 'Português', '480', '450g', '14+'),
(34, 'Desejo (Série Crave)', 'Tracy Wolff', 'R$ 45,90', 'Romance Fantasia', 0, '34.jpg', 'Bryn chega à Vamp U sem saber que está no meio de uma guerra sobrenatural. Romance intenso e cheio de mistério com vampiros, dragões e feras.', 'Intrínseca', '2020', '1ª edição', 'Português', '464', '440g', '16+'),
(35, 'Contos de Grimm', 'Irmãos Grimm', 'R$ 29,90', 'Contos', 0, '36.jpg', 'A coletânea mais famosa dos irmãos Grimm reunindo contos clássicos como Chapeuzinho Vermelho, Rapunzel e Branca de Neve nas versões originais mais sombrias.', 'Zahar', '1812', 'Edição comentada', 'Português', '832', '780g', '12+'),
(36, 'Contos de Fadas', 'Vários Autores', 'R$ 27,90', 'Contos', 0, '35.jpg', 'Seleção de contos de fadas de diversas tradições europeias, reunindo histórias de magia, amor e aventura que atravessam gerações.', 'Zahar', '2002', '1ª edição', 'Português', '320', '300g', '10+'),
(37, 'Ficções', 'Jorge Luis Borges', 'R$ 38,90', 'Contos', 1, '37.jpg', 'Uma das obras mais importantes da literatura latino-americana, reunindo 17 contos que exploram labirintos, infinitos e realidades alternativas com maestria única.', 'Companhia das Letras', '1944', 'Edição especial', 'Português', '128', '150g', '16+'),
(38, 'Primeiras Estórias', 'João Guimarães Rosa', 'R$ 36,90', 'Contos', 0, '38.jpg', '21 contos do mestre da prosa brasileira, explorando o sertão, a condição humana e o universo mítico do interior do Brasil com linguagem inovadora.', 'Nova Fronteira', '1962', '4ª edição', 'Português', '240', '230g', '16+'),
(39, 'Laços de Família', 'Clarice Lispector', 'R$ 34,90', 'Contos', 0, '39.jpg', 'Clarice Lispector revela o cotidiano feminino em 13 contos marcados por crises existenciais, epifanias e uma prosa de rara intensidade poética.', 'Rocco', '1960', '3ª edição', 'Português', '176', '170g', '16+'),
(40, 'Contos Novos', 'Mário de Andrade', 'R$ 30,90', 'Contos', 0, '40.jpg', 'Coletânea de contos do autor modernista brasileiro, explorando personagens populares, folclore e a cidade de São Paulo com humor e crítica social.', 'Livraria Martins Editora', '1947', '2ª edição', 'Português', '200', '190g', '14+'),
(41, 'Edgar Allan Poe - Vol. 1', 'Edgar Allan Poe', 'R$ 35,90', 'Contos', 0, '41.jpg', 'Volume 1 da obra completa de Poe, reunindo seus melhores contos de terror e mistério, incluindo O Coração Delator e A Queda da Casa de Usher.', 'Zahar', '1843', 'Edição bilíngue', 'Português/Inglês', '320', '300g', '14+'),
(42, 'Histórias Extraordinárias', 'Edgar Allan Poe', 'R$ 33,90', 'Contos', 0, '42.jpg', 'Antologia com os contos mais extraordinários de Poe, mestre do terror psicológico, incluindo O Poço e o Pêndulo e O Escaravelho de Ouro.', 'Martin Claret', '1840', '2ª edição', 'Português', '304', '290g', '14+'),
(43, 'O Aleph', 'Jorge Luis Borges', 'R$ 37,90', 'Contos', 0, '43.jpg', '17 contos que exploram o infinito, a identidade e o tempo em construções narrativas impossíveis que definiram a literatura fantástica do século XX.', 'Companhia das Letras', '1949', 'Edição especial', 'Português', '208', '200g', '16+'),
(44, 'Doze Contos Peregrinos', 'Gabriel García Márquez', 'R$ 38,90', 'Contos', 0, '44.jpg', '12 contos escritos ao longo de 18 anos, reunindo personagens europeus que vivem situações extraordinárias com a magia realista característica de García Márquez.', 'Record', '1992', '1ª edição', 'Português', '192', '185g', '16+'),
(45, 'Antes que o Café Esfrie', 'Toshikazu Kawaguchi', 'R$ 39,90', 'Contos', 1, '45.jpg', 'Num café de Tóquio, uma fenda no tempo permite visitar o passado. Quatro histórias de amor, perda e esperança que tocam profundamente o coração.', 'Intrínseca', '2015', '1ª edição', 'Português', '224', '215g', '14+'),
(46, 'Nove Histórias', 'J.D. Salinger', 'R$ 33,90', 'Contos', 0, '46.jpg', 'Nove histórias brilhantes e perturbadoras do autor de O Apanhador no Campo de Centeio, explorando personagens à beira do colapso emocional.', 'Editora do Autor', '1953', '2ª edição', 'Português', '208', '200g', '16+'),
(47, 'Felicidade Clandestina', 'Clarice Lispector', 'R$ 32,90', 'Contos', 0, '47.jpg', 'Clarice Lispector revela o prazer da leitura e o desejo em contos que exploram a infância, a feminilidade e o cotidiano com sensibilidade única.', 'Rocco', '1971', '3ª edição', 'Português', '112', '120g', '16+'),
(48, 'O Rei de Amarelo', 'Robert W. Chambers', 'R$ 36,90', 'Contos', 0, '48.jpg', 'Contos interligados que formam um mito sobre o Rei de Amarelo, peça teatral que enlouquece quem a lê. Obra seminal do horror sobrenatural americano.', 'Darkside Books', '1895', '1ª edição brasileira', 'Português', '224', '215g', '16+'),
(49, 'Manual da Faxineira', 'Lucia Berlin', 'R$ 42,90', 'Contos', 0, '49.jpg', 'Contos autobiográficos de Lucia Berlin sobre mulheres que trabalham como faxineiras, enfermeiras e telefonistas - vida real com prosa perfeccionista.', 'Companhia das Letras', '2015', '1ª edição', 'Português', '400', '380g', '16+'),
(50, 'Histórias de Amor', 'Rubem Fonseca', 'R$ 35,90', 'Contos', 0, '50.jpg', 'Rubem Fonseca explora o amor, o desejo e a violência urbana em contos que revelam o lado mais cru e apaixonado da natureza humana.', 'Companhia das Letras', '1997', '2ª edição', 'Português', '208', '200g', '18+'),
(51, 'Em Todos os Sentidos', 'Camila Antunes', 'R$ 38,90', 'Ficção Cristã', 1, '67.jpg', 'Uma jovem cristã navega o amor, a fé e os limites em um romance que equilibra emoção e valores bíblicos com personagens cativantes.', 'Chara', '2021', '1ª edição', 'Português', '280', '265g', '14+'),
(52, 'Os Clãs da Lua', 'Babi A. Sette', 'R$ 38,90', 'Ficção Cristã', 0, '66.jpg', 'Em um mundo de clãs e luas, jovens enfrentam escolhas de fé, amor e pertencimento numa narrativa fantástica de inspiração cristã.', 'Chara', '2020', '1ª edição', 'Português', '304', '290g', '14+'),
(53, 'As Andorinhas de um continente em chamas', 'Gabriela Fernandes', 'R$ 36,90', 'Ficção Cristã', 0, '65.jpg', 'Numa Europa em chamas, jovens andorinhas são símbolos de esperança e resistência. Fé, coragem e amor diante da perseguição.', 'Chara', '2019', '1ª edição', 'Português', '288', '275g', '14+'),
(54, 'Os Pardais do Velho Mundo', 'Gabriela Fernandes', 'R$ 36,90', 'Ficção Cristã', 0, '64.jpg', 'Continuação da saga das Andorinhas, onde os personagens enfrentam provações maiores e descobrem que a fé é o elo que une o velho e o novo mundo.', 'Chara', '2020', '1ª edição', 'Português', '288', '275g', '14+'),
(55, 'Encarando a Verdade', 'Thamires Marinho', 'R$ 35,90', 'Ficção Cristã', 0, '63.jpg', 'Uma jovem que evita confrontos aprende sobre honestidade, coragem e o amor que transforma quando é obrigada a encarar a verdade sobre si mesma.', 'Chara', '2021', '1ª edição', 'Português', '256', '245g', '14+'),
(56, 'Deixa Nevar', 'Camila Antunes', 'R$ 35,90', 'Ficção Cristã', 0, '62.jpg', 'Numa cidade coberta de neve, dois jovens com passados difíceis descobrem que deixar nevar significa também deixar Deus agir no coração.', 'Chara', '2022', '1ª edição', 'Português', '272', '260g', '14+'),
(57, 'A Escolha do Verão', 'Sara Gusella', 'R$ 35,90', 'Ficção Cristã', 0, '61.jpg', 'Um verão, uma escolha e um amor inesperado transformam a vida de uma jovem que aprende que o plano de Deus é sempre melhor que o seu.', 'Chara', '2021', '1ª edição', 'Português', '264', '250g', '14+'),
(58, 'A Pedra e o Dragão', 'Kathryn Butler', 'R$ 39,90', 'Ficção Cristã', 0, '60.jpg', 'Ambientado na Escócia medieval, um médico cristão enfrenta uma ameaça sobrenatural e descobre que a verdadeira batalha é espiritual.', 'Vida', '2020', '1ª edição', 'Português', '320', '305g', '14+'),
(59, 'Esposa Sob Medida', 'Noemi Nicoletti', 'R$ 37,90', 'Ficção Cristã', 0, '59.jpg', 'Valentina aceita um casamento arranjado sem esperar que o contrato traga amor de verdade. Uma história sobre graça, perdão e redenção.', 'Chara', '2021', '1ª edição', 'Português', '288', '275g', '14+'),
(60, 'Círculos não são infinitos', 'Vitória Souza', 'R$ 36,90', 'Ficção Cristã', 0, '58.jpg', 'Vitória Souza escreve sobre amizade, fé e cura emocional numa história que mostra que os círculos de dor têm início, mas também podem ter fim.', 'Chara', '2022', '1ª edição', 'Português', '256', '245g', '14+'),
(61, 'Aurora', 'Vitória Souza', 'R$ 36,90', 'Ficção Cristã', 0, '57.jpg', 'Aurora é uma jovem que busca sua identidade em meio à dor e ao passado. Uma história luminosa de fé e restauração.', 'Chara', '2023', '1ª edição', 'Português', '272', '260g', '14+'),
(62, 'Grama de Vidro', 'Débora Ciampi Eller', 'R$ 35,90', 'Ficção Cristã', 0, '56.jpg', 'Uma jovem descobre que as aparências enganam - inclusive as suas - numa história cristã sobre aceitação, identidade e amor verdadeiro.', 'Chara', '2022', '1ª edição', 'Português', '264', '250g', '14+'),
(63, 'De Repente Ester', 'Kell Carvalho', 'R$ 36,90', 'Ficção Cristã', 0, '55.jpg', 'Ester desperta em um mundo que não reconhece, mas descobre que Deus já preparou o caminho. Uma história de propósito e fé.', 'Chara', '2021', '1ª edição', 'Português', '272', '260g', '14+'),
(64, 'Cidades Pequenas Não Guardam Segredos', 'Kézia Garcia', 'R$ 37,90', 'Ficção Cristã', 0, '54.jpg', 'Numa pequena cidade do interior, segredos do passado emergem e testam a fé e os relacionamentos de seus moradores.', 'Chara', '2022', '1ª edição', 'Português', '280', '265g', '14+'),
(65, 'Sons de Ferrugem e Ecos de Borboleta', 'Noemi Nicoletti', 'R$ 37,90', 'Ficção Cristã', 0, '53.jpg', 'Uma história sobre perdas profundas e a beleza inesperada que nasce delas, com a fé como fio condutor entre sons de ferrugem e asas de borboleta.', 'Chara', '2021', '1ª edição', 'Português', '256', '245g', '14+'),
(66, 'Se pudesse contar as Estrelas', 'Becca Mackenzie', 'R$ 38,90', 'Ficção Cristã', 0, '52.jpg', 'Primeiro volume da duologia de Becca Mackenzie, onde uma jovem cristã enfrenta escolhas impossíveis sob um céu estrelado e cheio de promessas.', 'Chara', '2020', '1ª edição', 'Português', '288', '275g', '14+'),
(67, 'Se pudesse ver as Estrelas', 'Becca Mackenzie', 'R$ 38,90', 'Ficção Cristã', 0, '51.jpg', 'Conclusão da duologia, onde fé e amor se entrelaçam numa jornada de autodescoberta sob o mesmo céu de estrelas que guiou tudo desde o início.', 'Chara', '2021', '1ª edição', 'Português', '296', '280g', '14+'),
